import { useEffect, useState } from "react";
import { getCustomerProducts, purchaseAirtime, purchaseData } from "@/lib/vtu.functions";
import { toast } from "sonner";
import { useQueryClient } from "@tanstack/react-query";
type Product = {
  id: string;
    service: "data" | "airtime";
      network_name: string;
        plan_name: string;
          validity: string | null;
            selling_price_kobo: number | null;
              min_amount_kobo: number | null;
                max_amount_kobo: number | null;
                };

                export function CustomerProducts({
                  service,
                  }: {
                    service: "data" | "airtime";
                    }) {
                const [products, setProducts] = useState<Product[]>([]);
                        const [loading, setLoading] = useState(true);
                          const [error, setError] = useState("");
                            const [purchasesAvailable, setPurchasesAvailable] = useState(false);

                            useEffect(() => {
                                let active = true;

                                    getCustomerProducts()
                                          .then((result) => {
                                                  if (active) {
                                                            setPurchasesAvailable(result.purchasesAvailable === true);
                                                            setProducts(
                                                                        result.products.filter((product) => product.service === service)
                                                                                  );
                                                                                          }
                                                                                                })
                                                                                                      .catch(() => {
                                                                                                              if (active) setError("We couldn't load products. Please try again.");
                                                                                                                    })
                                                                                                                          .finally(() => {
                                                                                                                                  if (active) setLoading(false);
                                                                                                                                        });

                                                                                                                                            return () => {
                                                                                                                                                  active = false;
                                                                                                                                                      };
                                                                                                                                                        }, [service]);

                                                                                                                                                          const formatPrice = (kobo: number | null) =>
                                                                                                                                                              kobo === null
                                                                                                                                                                    ? "Price unavailable"
                                                                                                                                                                          : `₦${(kobo / 100).toLocaleString("en-NG")}`;
  const qc = useQueryClient();
    const [networkId, setNetworkId] = useState(1);
      const [networkName, setNetworkName] = useState("MTN");
        const [phone, setPhone] = useState("");
          const [amount, setAmount] = useState("100");
            const [submitting, setSubmitting] = useState(false);
  const [selectedDataPlan, setSelectedDataPlan] = useState<Product | null>(null);
  const [dataRecipient, setDataRecipient] = useState("");
  const [confirmation, setConfirmation] = useState<"data" | "airtime" | null>(null);

              const NETWORKS = [
                  { id: 1, name: "MTN", color: "bg-amber-400 text-black border-amber-500" },
                      { id: 2, name: "Airtel", color: "bg-red-500 text-white border-red-600" },
                          { id: 3, name: "GLO", color: "bg-emerald-600 text-white border-emerald-700" },
                              { id: 4, name: "9mobile", color: "bg-lime-600 text-white border-lime-700" },
                                ];

                                  async function confirmPurchase() {
    if (!confirmation || submitting) return;
    setSubmitting(true);
    try {
      if (confirmation === "data" && selectedDataPlan) {
        if (!purchasesAvailable) {
          toast.error("Data purchases are still being tested. Your wallet has not been charged.");
          return;
        }
        const result = await purchaseData({ data: { productId: selectedDataPlan.id, phone: dataRecipient.trim() } });
        toast.success(result.message);
        setDataRecipient("");
        setSelectedDataPlan(null);
      } else if (confirmation === "airtime") {
        const res = await purchaseAirtime({ data: { networkId, networkName, phone: phone.trim(), amountNaira: parseInt(amount, 10) } });
        toast.success(res.message);
        setPhone("");
      }
      setConfirmation(null);
      await qc.invalidateQueries({ queryKey: ["wallet"] });
      if (confirmation === "data") await qc.invalidateQueries({ queryKey: ["customer-purchase-badges"] });
      await qc.invalidateQueries({ queryKey: ["admin", "ledger"] });
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Purchase needs review.");
    } finally {
      setSubmitting(false);
    }
  }

  function handleDataBuy() {
    if (!selectedDataPlan) {
      toast.error("Select a data plan first.");
      return;
    }
    if (dataRecipient.replace(/\D/g, "").length < 10) {
      toast.error("Enter a valid Nigerian phone number.");
      return;
    }
    setConfirmation("data");
  }

  async function handleBuy(e: React.FormEvent) {
                                      e.preventDefault();
                                          const numAmount = parseInt(amount, 10);
                                              if (!numAmount || numAmount < 50 || numAmount > 10000) {
                                                    toast.error("Enter an amount between ₦50 and ₦10,000.");
                                                          return;
                                                              }
                                                                  if (phone.replace(/\D/g, "").length < 10) {
                                                                        toast.error("Enter a valid Nigerian phone number (e.g. 08012345678).");
                                                                              return;
                                                                                  }
    setConfirmation("airtime");
  }
                                                                                                                                                            
                                                                                                                                                                            return (
                                                                                                                                                                                <div className="space-y-5">
                                                    {!purchasesAvailable && <div role="status" className="rounded-xl border border-amber-500/40 bg-amber-500/10 p-4 text-sm"><p className="font-semibold">Purchases are not available yet</p><p className="mt-1 text-muted-foreground">We are completing provider verification. You can view available plans, but no order will be submitted or wallet charged.</p></div>}
                                                                                                                                                                                            {service === "airtime" ? (
                                                                                                                                                                                                    <form onSubmit={handleBuy} className="rounded-2xl border bg-card p-5 shadow-soft space-y-4">
                                                                                                                                                                                                              <div>
                                                                                                                                                                                                                          <label className="text-xs font-semibold uppercase text-muted-foreground">Select Network</label>
                                                                                                                                                                                                                                      <div className="mt-2 grid grid-cols-4 gap-2">
                                                                                                                                                                                                                                                    {NETWORKS.map((net) => (
                                                                                                                                                                                                                                                                    <button
                                                                                                                                                                                                                                                                                      key={net.id}
                                                                                                                                                                                                                                                                                                        type="button"
                                                                                                                                                                                                                                                                                                                          onClick={() => { setNetworkId(net.id); setNetworkName(net.name); }}
                                                                                                                                                                                                                                                                                                                                            className={`rounded-xl border py-2.5 text-center text-xs font-bold transition-all ${
                                                                                                                                                                                                                                                                                                                                                                networkId === net.id ? `${net.color} ring-2 ring-primary ring-offset-2 shadow-sm` : "bg-muted text-muted-foreground opacity-60"
                                                                                                                                                                                                                                                                                                                                                                                  }`}
                                                                                                                                                                                                                                                                                                                                                                                                  >
                                                                                                                                                                                                                                                                                                                                                                                                                    {net.name}
                                                                                                                                                                                                                                                                                                                                                                                                                                    </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                  ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <label className="text-xs font-semibold uppercase text-muted-foreground">Recipient Phone Number</label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <input
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        type="tel"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      required
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    placeholder="e.g. 08012345678"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  value={phone}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                onChange={(e) => setPhone(e.target.value)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              className="mt-1 h-11 w-full rounded-xl border bg-background px-3 font-mono text-sm tracking-wide focus:outline-none focus:ring-2 focus:ring-primary"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <label className="text-xs font-semibold uppercase text-muted-foreground">Recharge Amount (₦)</label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <input
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    type="number"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  required
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                min={50}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              max={10000}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            value={amount}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          onChange={(e) => setAmount(e.target.value)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        className="mt-1 h-11 w-full rounded-xl border bg-background px-3 font-semibold text-sm focus:outline-none focus:ring-2 focus:ring-primary"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div className="mt-2 flex gap-2">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {[100, 200, 500, 1000].map((val) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <button
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                key={val}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  type="button"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    onClick={() => setAmount(String(val))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      className="rounded-lg border bg-muted/60 px-3 py-1 text-xs font-medium hover:bg-muted"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ₦{val}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <button
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  type="submit"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              disabled={submitting || !purchasesAvailable}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          className="w-full rounded-xl bg-primary py-3 font-semibold text-primary-foreground shadow transition hover:opacity-90 disabled:opacity-50"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {submitting ? "Processing Airtime..." : `Pay ₦${amount || "0"} Airtime`}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </form>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ) : (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <form onSubmit={(e) => { e.preventDefault(); toast.info("Data ordering is not enabled yet. Your wallet has not been charged."); }} className="space-y-4 rounded-2xl border bg-card p-4 shadow-soft">
  <div><h2 className="font-semibold">Buy a data bundle</h2><p className="mt-1 text-sm text-muted-foreground">Choose a plan below, then enter the recipient's phone number.</p></div>
  <div><label className="text-xs font-semibold uppercase text-muted-foreground">Recipient phone number</label>
    <input type="tel" inputMode="tel" placeholder="e.g. 08012345678" value={dataRecipient} onChange={(e) => setDataRecipient(e.target.value)} className="mt-1 h-11 w-full rounded-xl border bg-background px-3 font-mono text-sm focus:outline-none focus:ring-2 focus:ring-primary" />
    <p className="mt-1 text-xs text-muted-foreground">Check the number carefully before placing an order.</p></div>
  {selectedDataPlan && <div className="rounded-xl bg-muted/60 p-3 text-sm"><p className="font-semibold">Selected: {selectedDataPlan.network_name} — {selectedDataPlan.plan_name}</p><p className="mt-1">Total: <strong>{formatPrice(selectedDataPlan.selling_price_kobo)}</strong></p></div>}
  <button type="submit" disabled={!selectedDataPlan || !/^0\d{10}$/.test(dataRecipient.replace(/\D/g, "")) || !purchasesAvailable || submitting} className="w-full rounded-xl bg-primary py-3 font-semibold text-primary-foreground disabled:cursor-not-allowed disabled:opacity-50">Continue to purchase</button>
  <p className="text-xs text-muted-foreground">Ordering is locked while provider delivery verification is completed. This form will not charge your wallet.</p>
</form>
)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        

                                                                                                                                                                                                                                              {loading && (
                                                                                                                                                                                                                                                      <p className="py-8 text-center text-sm text-muted-foreground">
                                                                                                                                                                                                                                                                Loading products...
                                                                                                                                                                                                                                                                        </p>
                                                                                                                                                                                                                                                                              )}

                                                                                                                                                                                                                                                                                    {error && (
                                                                                                                                                                                                                                                                                            <p className="rounded-xl bg-destructive/10 p-4 text-sm text-destructive">
                                                                                                                                                                                                                                                                                                      {error}
                                                                                                                                                                                                                                                                                                              </p>
                                                                                                                                                                                                                                                                                                                    )}

                                                                                                                                                                                                                                                                                                                          {!loading && !error && products.length === 0 && (
                                                                                                                                                                                                                                                                                                                                  <div className="rounded-2xl border bg-card p-6 text-center">
                                                                                                                                                                                                                                                                                                                                            <h2 className="font-semibold">No products available yet</h2>
                                                                                                                                                                                                                                                                                                                                                      <p className="mt-2 text-sm text-muted-foreground">
                                                                                                                                                                                                                                                                                                                                                                  Please check again later.
                                                                                                                                                                                                                                                                                                                                                                            </p>
                                                                                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                                                                                          )}

                                                                                                                                                                                                                                                                                                                                                                                                {!loading && !error && products.length > 0 && (
                                                                                                                                                                                                                                                                                                                                                                                                        <div className="space-y-3">
                                                                                                                                                                                                                                                                                                                                                                                                                  {products.map((product) => (
                                                                                                                                                                                                                                                                                                                                                                                                                              <div
                                                                                                                                                                                                                                                                                                                                                                                                                                            key={product.id}
                                                                                                                                                                                                                                                                                                                                                                                                                                                          className="flex items-center justify-between gap-3 rounded-2xl border bg-card p-4 shadow-soft"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div className="min-w-0">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <p className="font-semibold">{product.plan_name}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <p className="text-sm text-muted-foreground">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {product.network_name}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {product.validity ? ` • ${product.validity}` : ""}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {product.service === "airtime" && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <p className="mt-1 text-xs text-muted-foreground">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              Amount range: {formatPrice(product.min_amount_kobo)} –{" "}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {formatPrice(product.max_amount_kobo)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div className="shrink-0 text-right">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <p className="font-bold">{formatPrice(product.selling_price_kobo)}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {product.service === "data" && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <button type="button" onClick={() => setSelectedDataPlan(product)} aria-pressed={selectedDataPlan?.id === product.id} className={`mt-2 rounded-lg border px-3 py-2 text-xs font-semibold transition ${selectedDataPlan?.id === product.id ? "border-primary bg-primary/10 text-primary" : "hover:border-primary"}`}>{selectedDataPlan?.id === product.id ? "Selected" : "Select plan"}</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
      {service === "data" && (
        <div className="rounded-2xl border bg-card p-5 shadow-soft space-y-4">
          <div>
            <p className="font-semibold">Your selected data plan</p>
            <p className="text-sm text-muted-foreground">
              {selectedDataPlan ? `${selectedDataPlan.network_name} • ${selectedDataPlan.plan_name} • ${formatPrice(selectedDataPlan.selling_price_kobo)}` : "Choose a plan above to continue."}
            </p>
          </div>
          <div>
            <label htmlFor="data-recipient-phone" className="text-xs font-semibold uppercase text-muted-foreground">Recipient phone number</label>
            <input id="data-recipient-phone" value={dataRecipient} onChange={(e) => setDataRecipient(e.target.value)} inputMode="tel" autoComplete="tel" placeholder="08012345678" className="mt-2 w-full rounded-xl border bg-background px-3 py-3" />
            <p className="mt-1 text-xs text-muted-foreground">Check the number carefully before submitting. Data sent to a wrong number may not be recoverable.</p>
          </div>
          <button type="button" onClick={handleDataBuy} disabled={!selectedDataPlan || submitting} className="w-full rounded-xl bg-primary px-4 py-3 font-semibold text-primary-foreground disabled:cursor-not-allowed disabled:opacity-50">
            {submitting ? "Processing..." : purchasesAvailable ? "Buy data" : "Data purchases coming soon"}
          </button>
          {!purchasesAvailable && <p className="text-xs text-muted-foreground">Testing mode: selecting a plan will not charge your wallet.</p>}
        </div>
      )}
      {confirmation && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-4" role="presentation">
          <div role="dialog" aria-modal="true" aria-labelledby="purchase-confirm-title" className="w-full max-w-md space-y-4 rounded-2xl border bg-card p-5 shadow-2xl">
            <h2 id="purchase-confirm-title" className="text-lg font-bold">Confirm your purchase</h2>
            <div className="space-y-2 rounded-xl bg-muted/50 p-4 text-sm">
              <p><span className="text-muted-foreground">Network:</span> <strong>{confirmation === "data" ? selectedDataPlan?.network_name : networkName}</strong></p>
              {confirmation === "data" ? (
                <p><span className="text-muted-foreground">Plan:</span> <strong>{selectedDataPlan?.plan_name}</strong></p>
              ) : (
                <p><span className="text-muted-foreground">Airtime:</span> <strong>₦{parseInt(amount || "0", 10).toLocaleString("en-NG")}</strong></p>
              )}
              <p><span className="text-muted-foreground">Recipient:</span> <strong>{confirmation === "data" ? dataRecipient : phone}</strong></p>
              <p><span className="text-muted-foreground">Amount:</span> <strong>{confirmation === "data" ? formatPrice(selectedDataPlan?.selling_price_kobo ?? null) : `₦${parseInt(amount || "0", 10).toLocaleString("en-NG")}`}</strong></p>
            </div>
            <div className="rounded-xl border border-amber-500/40 bg-amber-500/10 p-3 text-sm">
              <p className="font-semibold text-amber-700 dark:text-amber-300">⚠️ Check the phone number carefully.</p>
              <p className="mt-1">Airtime or data sent to a wrong number may not be recoverable. Smart Browsers cannot guarantee reversal of an incorrect recipient number.</p>
            </div>
            <div className="grid grid-cols-2 gap-3">
              <button type="button" disabled={submitting} onClick={() => setConfirmation(null)} className="rounded-xl border px-4 py-3 font-medium disabled:opacity-50">Cancel</button>
              <button type="button" disabled={submitting || (confirmation === "data" && !purchasesAvailable)} onClick={confirmPurchase} className="rounded-xl bg-primary px-4 py-3 font-semibold text-primary-foreground disabled:opacity-50">{submitting ? "Processing…" : confirmation === "data" && !purchasesAvailable ? "Unavailable" : "Confirm & Pay"}</button>
            </div>
          </div>
        </div>
      )}
 </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }